    <script type="module">
        /* 更新进度条辅助函数 */
        function updateProgressBar(barId, valueId, rawValue, min = 0, max = 100, color = null) {
            const numericValue = parseFloat(rawValue);
            if (!isNaN(numericValue)) {
                const clampedValue = _.clamp(numericValue, min, max);
                const percentage = max - min === 0 ? 0 : ((clampedValue - min) / (max - min)) * 100;

                $(`#${valueId}`).text(clampedValue);
                const cssProps = { width: `${percentage}%` };
                if (color) {
                    cssProps.backgroundImage = 'none';
                    cssProps.backgroundColor = color;
                }
                $(`#${barId}`).css(cssProps);
            } else {
                $(`#${valueId}`).text(rawValue);
            }
        }

        /* 填充状态栏数据 */
        function populateCharacterData() {
            try {
                const all_variables = getAllVariables();
                const characterData = all_variables.stat_data;

                if (!characterData) {
                    $('#status-card').html("<div class='error-tip'>无法加载状态数据</div>");
                    return;
                }

                /* König 好感度：范围 0 ~ 100 */
                updateProgressBar(
                    'konig-affection-bar',
                    'konig-affection',
                    _.get(characterData, 'König.好感度', 0),
                    0, 100, '#c81d3c'
                );

                /* König 性欲值：范围 0 ~ 100 */
                updateProgressBar(
                    'konig-desire-bar',
                    'konig-desire',
                    _.get(characterData, 'König.性欲值', 0),
                    0, 100, '#8b1a2b'
                );

                /* König 羞耻值：范围 0 ~ 100 */
                updateProgressBar(
                    'konig-shame-bar',
                    'konig-shame',
                    _.get(characterData, 'König.羞耻值', 0),
                    0, 100, '#d46a86'
                );

                /* 文本类属性 */
                $('#konig-outfit').text(_.get(characterData, 'König.衣着', 'N/A'));
                $('#konig-status-badge').text(_.get(characterData, 'König.状态', 'N/A'));
                $('#konig-inner-voice').text(_.get(characterData, 'König.心声', 'N/A'));
            } catch (error) {
                $('#status-card').html(`<div class='error-tip'>状态栏加载出错: ${error.message}</div>`);
            }
        }

        /* 初始化 */
        async function init() {
            /* 等待 MVU 系统初始化完成 */
            await waitGlobalInitialized('Mvu');

            /* 填充数据 */
            populateCharacterData();
        }

        $(errorCatched(init));
